 18	      if (filterType !== 'ALL' && e.type !== filterType) return false;
 19	      if (filterPriority !== 'ALL' && e.priority !== filterPriority) return false;
 20	      if (filterProject !== 'ALL' && e.project_slug !== filterProject) return false;
