 23	
 24	    if (!filtered.length) {
 25	      return '<p class="text-muted mt-16">No insights found.</p>';
 26	    }
 27	
 28	    return filtered.map(function (e) {
 29	      var priorityClass = e.priority ? ' priority-' + e.priority : '';
 30	      var contextHtml = '';
 31	      if (e.context && typeof e.context === 'object') {
 32	        var ctxItems = Object.entries(e.context).map(function (pair) {
 33	          return '<span><strong>' + escapeHtml(pair[0]) + ':</strong> ' + escapeHtml(String(pair[1])) + '</span>';
 34	        }).join('<br>');
 35	        contextHtml =
 36	          '<div class="comment-context">' +
 37	            ctxItems +
 38	          '</div>';
 39	      }
 40	      var projectLink = e.repository_name
 41	        ? '<a href="#/projects/' + encodeURIComponent(e.repository_name) + '/' + encodeURIComponent(e.project_slug) + '">' + escapeHtml(e.project_slug) + '</a>'
 42	        : escapeHtml(e.project_slug);
 43	      return '<div class="comment-card' + priorityClass + '">' +
 44	        '<div class="comment-meta">' +
 45	          projectLink +
 46	          ' &mdash; ' +
 47	          escapeHtml(e.agent || '\u2014') +
 48	          ' <span class="comment-type">' + escapeHtml(e.type || '') + '</span>' +
 49	          ' <span>' + escapeHtml(formatDate(e.timestamp)) + '</span>' +
 50	        '</div>' +
 51	        '<div class="comment-body">' + escapeHtml(e.note || '') + '</div>' +
 52	        contextHtml +
 53	      '</div>';
 54	    }).join('');
 55	  }
