 21	import { describe, it, expect, beforeAll, vi } from 'vitest';
 22	import { readFileSync } from 'node:fs';
 23	import { join } from 'node:path';
 24	import vm from 'node:vm';
 25	
 26	// ---------------------------------------------------------------------------
 27	// Load scripts
 28	// ---------------------------------------------------------------------------
 29	
 30	const publicDir = join(__dirname, '../../gui/public');
 31	
 32	const utilsJs     = readFileSync(join(publicDir, 'utils.js'), 'utf-8');
 33	const insightsJs  = readFileSync(join(publicDir, 'views/insights.js'), 'utf-8');
 34	const knowledgeJs = readFileSync(join(publicDir, 'views/knowledge.js'), 'utf-8');
 35	
 36	// ---------------------------------------------------------------------------
 37	// Global type stubs
 38	// ---------------------------------------------------------------------------
 39	
 40	declare global {
 41	  // eslint-disable-next-line no-var
 42	  var renderInsights:  (app: HTMLElement) => void;
 43	  // eslint-disable-next-line no-var
 44	  var renderKnowledge: (app: HTMLElement) => void;
 45	  // eslint-disable-next-line no-var
 46	  var API: {
 47	    getInsights:      ReturnType<typeof vi.fn>;
 48	    getKnowledge:     ReturnType<typeof vi.fn>;
 49	    updateKnowledge:  ReturnType<typeof vi.fn>;
 50	    deleteKnowledge:  ReturnType<typeof vi.fn>;
 51	    promoteKnowledge: ReturnType<typeof vi.fn>;
 52	    moveKnowledge:    ReturnType<typeof vi.fn>;
 53	  };
 54	  // eslint-disable-next-line no-var
 55	  var Router: {
 56	    _setPolling:   ReturnType<typeof vi.fn>;
 57	    _clearPolling: ReturnType<typeof vi.fn>;
 58	  };
 59	  // eslint-disable-next-line no-var
 60	  var showLoading: ReturnType<typeof vi.fn>;
 61	  // eslint-disable-next-line no-var
 62	  var showError:   ReturnType<typeof vi.fn>;
 63	  // eslint-disable-next-line no-var
 64	  var formatDate:  (s: string) => string;
 65	  // eslint-disable-next-line no-var
 66	  var escapeHtml:  (s: string) => string;
 67	}
