 69	// ---------------------------------------------------------------------------
 70	// Setup: install globals, load scripts once
 71	// ---------------------------------------------------------------------------
 72	
 73	beforeAll(() => {
 74	  // Install utils.js globals (escapeHtml, formatDate, etc.)
 75	  vm.runInThisContext(utilsJs);
 76	
 77	  // Stub showLoading / showError so the view scripts can call them.
 78	  (globalThis as Record<string, unknown>)['showLoading'] = vi.fn();
 79	  (globalThis as Record<string, unknown>)['showError']   = vi.fn();
 80	
 81	  // Stub Router.
 82	  (globalThis as Record<string, unknown>)['Router'] = {
 83	    _setPolling:   vi.fn(),
 84	    _clearPolling: vi.fn(),
