229	  /**
230	   * Minimal knowledge insight with origin_plan and repository_name.
231	   * Defaults to `scope: 'global'` so it passes the default `activeTab='global'`
232	   * filter in renderKnowledge without needing to simulate a tab click.
233	   */
234	  function makeInsight(overrides: Record<string, unknown> = {}) {
235	    return {
236	      id:              1,
237	      scope:           'global',
238	      repository_name: 'some-repo',
239	      category:        'architecture',
240	      title:           'Test insight',
241	      content:         'Some content here',
242	      tags:            ['tag-a'],
