251	  }
252	
253	  it('AC-2: renders a namespaced origin-plan link when repository_name is non-null', async () => {
254	    globalThis.API.getKnowledge = vi.fn().mockResolvedValue([makeInsight()]);
255	
256	    const app = document.createElement('div');
